Part of #3287

This PR modifies the `kore-rpc` server to use `aeson-pretty` for encoding the JSON responses. This means we can sort the object keys for better readability. e.g. message before the change:

```json
{
  "result": {
    "state": {
      "term": {
        "format": "KORE",
        "term": {
          "args": [
            {
              "args": [...],
              "tag": "App",
              "sorts": [],
              "name": "Lbl'-LT-'T'-GT-'"
            },
            {...}
          ],
          "tag": "App",
          "sorts": [],
          "name": "Lbl'-LT-'generatedTop'-GT-'"
        },
        "version": 1
      }
    },
    "next-states": [...],
    "reason": "branching",
    "depth": 0
  },
  "jsonrpc": "2.0",
  "id": 1
}
```

vs the new version:

```json
{
  "jsonrpc": "2.0",
  "id": 1,
  "result": {
    "reason": "branching",
    "depth": 0,
    "state": {
      "term": {
        "format": "KORE",
        "version": 1,
        "term": {
          "tag": "App",
          "name": "Lbl'-LT-'generatedTop'-GT-'",
          "sorts": [],
          "args": [
            {
              "tag": "App",
              "name": "Lbl'-LT-'T'-GT-'",
              "sorts": [],
              "args": [...]
            },
            {...}
          ]
        }
      }
    },
    "next-states": [...]
  }
}
```

